import {createApp} from './app.mjs';import catalog from './catalog.mjs';import aliases from './aliases.mjs';import compressed from './compressed.mjs';
export default {async fetch(request,env){if(!env.DB||!env.ASSETS)return new Response('Home Vibe hosting bindings are unavailable.',{status:503});const origin=new URL(request.url).origin;const readAsset=async name=>{const canonical=aliases[name]||name;const packed=compressed[canonical];const result=await env.ASSETS.fetch(new Request(origin+'/'+(packed||canonical)));if(!result.ok)return null;const body=packed?result.body.pipeThrough(new DecompressionStream('gzip')):result.body;const type=packed?({'html':'text/html; charset=utf-8','js':'text/javascript; charset=utf-8','css':'text/css; charset=utf-8','json':'application/json'}[canonical.split('.').at(-1)]):result.headers.get('content-type');return {bytes:new Uint8Array(await new Response(body).arrayBuffer()),type:type||'application/octet-stream'};};return createApp({db:env.DB,readAsset,catalog}).fetch(request);}};
